export const reportSchemaVersion='r1-report-v1';
export function datasetDefinition(id:string){const d=reportDatasets.find(d=>d.datasetId===id);if(!d)return null;return {...d,definitionVersion:reportSchemaVersion,fields:reportFields.filter(f=>f.datasetId===id).map(f=>({...f,allowedAggregations:[...new Set([...f.allowedAggregations,...(registeredMeasureInputs[f.fieldId]??[])])]})),metrics:registeredMetrics[id]??[],rowKeySchema:d.rowKey.split(','),sortKeys:['rowKey'],sourceSchemaVersions:{[d.producer]:d.producer==='M01'?'r1-m01-v1':'producer_contract_required'},allowedJoins:id==='workforce'?[{id:'person_contracts',target:'contractOperations',cardinality:'1:N',foreignKey:'personId',strategies:['distinct_root','preaggregate']}]:[]};}
export const producerDirectory=['M01','M19','M48','M32','M03','M06','M17','M18','M26','M37','M12','M16','M27','M11','M07'].map(producerId=>({producerId,configurationState:['M01','M19','M48','M32'].includes(producerId)?'internal':'not_configured',realIntegration:'not_executed',contractEvidence:null,recoveryCondition:'versioned producer contract and integration acceptance',owner:producerId+' implementation owner'}));
